/* initial formula
IF( ISPICKVAL(Industry,""), 0,20) + IF( ISPICKVAL(Rating,""), 0,20) + IF( LEN(BillingCity) = 0, 0,20) + IF(LEN(Phone) = 0, 0,20) + IF( ISPICKVAL(Type,""), 0,20) */

IF(LEN(BillingCity)=0,0,27.2727272727273) + IF(AND(NOT(ISPICKVAL(ER_Local_Merchant_Segmentation__c,"")),ISPICKVAL(ER_Global_Segmentation__c,"")),0,9.09090909090909) + IF(AND(ISPICKVAL(ER_Local_Merchant_Segmentation__c,""),ISPICKVAL(ER_Segment__c,"")),0,27.2727272727273) + IF(LEN(ER_NaceList__c)=0,0,9.09090909090909) + IF(LEN(ER_Registration_Number__c&ER_VAT_Number__c&ER_Other_Fiscal_ID__c)=0,0,27.2727272727273)
